-- AI Agent Workflow Builder core schema
create extension if not exists pgcrypto;
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, quota_limit int not null default 100, quota_used int not null default 0, quota_period_start timestamptz not null default date_trunc('month', now()), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.org_members (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check (role in ('owner','editor','viewer')), created_at timestamptz not null default now(), unique (org_id,user_id));
create index idx_org_members_user on public.org_members(user_id); create index idx_org_members_org on public.org_members(org_id);
create table public.workflows (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id) on delete cascade, name text not null, description text, created_by uuid not null references auth.users(id), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index idx_workflows_org on public.workflows(org_id);
create table public.workflow_steps (id uuid primary key default gen_random_uuid(), workflow_id uuid not null references public.workflows(id) on delete cascade, step_order int not null, type text not null check (type in ('llm_call','http_request','db_write','notify','conditional_branch','approval_gate')), name text not null default '', config jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique (workflow_id,step_order)); create index idx_steps_workflow on public.workflow_steps(workflow_id);
create table public.workflow_triggers (id uuid primary key default gen_random_uuid(), workflow_id uuid not null references public.workflows(id) on delete cascade, type text not null check (type in ('manual','webhook','scheduled','database_event')), config jsonb not null default '{}'::jsonb, is_enabled boolean not null default true, created_at timestamptz not null default now()); create index idx_triggers_workflow on public.workflow_triggers(workflow_id); create index idx_triggers_type on public.workflow_triggers(type);
create table public.workflow_runs (id uuid primary key default gen_random_uuid(), workflow_id uuid not null references public.workflows(id) on delete cascade, org_id uuid not null references public.organizations(id) on delete cascade, status text not null check (status in ('pending','running','paused','completed','failed')) default 'pending', trigger_type text not null default 'manual', triggered_by uuid references auth.users(id), current_step_order int not null default 0, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now()); create index idx_runs_workflow on public.workflow_runs(workflow_id); create index idx_runs_org on public.workflow_runs(org_id);
create table public.step_runs (id uuid primary key default gen_random_uuid(), workflow_run_id uuid not null references public.workflow_runs(id) on delete cascade, workflow_step_id uuid not null references public.workflow_steps(id) on delete cascade, status text not null check (status in ('pending','running','succeeded','failed','paused','skipped')) default 'pending', input jsonb, output jsonb, error text, attempt_count int not null default 0, approved_by uuid references auth.users(id), approved_at timestamptz, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now()); create index idx_step_runs_run on public.step_runs(workflow_run_id);
create table public.workflow_data (id uuid primary key default gen_random_uuid(), workflow_run_id uuid not null references public.workflow_runs(id) on delete cascade, step_run_id uuid not null references public.step_runs(id) on delete cascade, data jsonb not null, created_at timestamptz not null default now()); create index idx_workflow_data_run on public.workflow_data(workflow_run_id);
create table public.notification_events (id uuid primary key default gen_random_uuid(), workflow_run_id uuid not null references public.workflow_runs(id) on delete cascade, step_run_id uuid not null references public.step_runs(id) on delete cascade, channel text not null default 'slack', payload jsonb not null, delivered boolean not null default false, delivered_at timestamptz, created_at timestamptz not null default now());
create table public.watched_table_events (id uuid primary key default gen_random_uuid(), source_table text not null, operation text not null default 'INSERT', record_id text, payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create view public.org_usage_view as select o.id as org_id,o.quota_limit,o.quota_used,o.quota_period_start,round(o.quota_used::numeric/nullif(o.quota_limit,0)*100,1) as usage_pct from public.organizations o;
create function public.workflow_avg_run_duration_seconds(wf public.workflows) returns numeric language sql stable as $$ select avg(extract(epoch from (r.completed_at-r.started_at))) from public.workflow_runs r where r.workflow_id=wf.id and r.status='completed' and r.started_at is not null and r.completed_at is not null $$;
create function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
create trigger trg_organizations_updated_at before update on public.organizations for each row execute function public.set_updated_at();
create trigger trg_workflows_updated_at before update on public.workflows for each row execute function public.set_updated_at();
create function public.guard_last_owner() returns trigger language plpgsql as $$ declare remaining_owners int; begin if (TG_OP='DELETE' and OLD.role='owner') or (TG_OP='UPDATE' and OLD.role='owner' and NEW.role<>'owner') then select count(*) into remaining_owners from public.org_members where org_id=OLD.org_id and role='owner' and id<>OLD.id; if remaining_owners=0 then raise exception 'organization must retain at least one owner'; end if; end if; if TG_OP='DELETE' then return OLD; end if; return NEW; end; $$;
create trigger trg_guard_last_owner before update or delete on public.org_members for each row execute function public.guard_last_owner();
